// 100 Days of AI — static course browser.
// Reads docs/course.json (generated by tools/build_site_manifest.py), plays
// per-lesson YouTube videos, and links exercises/project to Google Colab.
// Progress is stored in the browser (localStorage) — nothing leaves your machine.

const STORE_KEY = "100days-progress-v1";

let COURSE = null;
let state = loadProgress();

function loadProgress() {
  try { return JSON.parse(localStorage.getItem(STORE_KEY)) || {}; }
  catch { return {}; }
}
function saveProgress() {
  localStorage.setItem(STORE_KEY, JSON.stringify(state));
}
function itemDone(key) { return !!state[key]; }
function setItem(key, val) {
  if (val) state[key] = true; else delete state[key];
  saveProgress();
}

// A day counts as "done" when its project (or, if none, its last lesson) is checked.
function dayDone(day) {
  return itemDone(`day_${day.day}_complete`);
}

// ── Boot ─────────────────────────────────────────────────────────────────────
// Cache-bust so a freshly deployed course.json isn't masked by the CDN/browser
// cache (GitHub Pages serves JSON with a ~10 min max-age).
fetch(`course.json?v=${Date.now()}`)
  .then(r => r.json())
  .then(data => { COURSE = data; renderSidebar(); route(); })
  .catch(err => {
    document.getElementById("main").innerHTML =
      `<div class="empty">Couldn't load <code>course.json</code>.<br>` +
      `Run <code>python tools/build_site_manifest.py</code> first.<br><br>${err}</div>`;
  });

window.addEventListener("hashchange", route);

function allDays() {
  return COURSE.sections.flatMap(s => s.days);
}
function findDay(n) {
  return allDays().find(d => d.day === n);
}

function route() {
  const m = location.hash.match(/day-(\d+)/);
  const n = m ? parseInt(m[1], 10) : (allDays()[0] && allDays()[0].day);
  const day = findDay(n) || allDays()[0];
  if (day) renderDay(day);
  markActive(day ? day.day : null);
  updateSummary();
}

// ── Sidebar ──────────────────────────────────────────────────────────────────
function renderSidebar() {
  const nav = document.getElementById("sidebar");
  nav.innerHTML = "";
  for (const section of COURSE.sections) {
    const t = document.createElement("div");
    t.className = "section-title";
    t.textContent = section.name;
    nav.appendChild(t);
    for (const day of section.days) {
      const a = document.createElement("a");
      a.className = "day-link";
      a.href = `#day-${day.day}`;
      a.dataset.day = day.day;
      a.innerHTML =
        `<span class="day-num">Day ${day.day}</span>` +
        `<span class="day-name">${escapeHtml(day.title)}</span>` +
        `<span class="check">✓</span>`;
      if (dayDone(day)) a.classList.add("done");
      nav.appendChild(a);
    }
  }
}

function markActive(dayNum) {
  document.querySelectorAll(".day-link").forEach(el => {
    el.classList.toggle("active", parseInt(el.dataset.day, 10) === dayNum);
  });
}

function updateSummary() {
  const total = allDays().length;
  const done = allDays().filter(dayDone).length;
  document.getElementById("progress-summary").textContent =
    `${done} / ${total} days complete`;
}

// ── Day view ─────────────────────────────────────────────────────────────────
function renderDay(day) {
  const main = document.getElementById("main");
  main.scrollTop = 0;
  main.innerHTML = "";

  const header = document.createElement("div");
  header.className = "day-header";
  header.innerHTML =
    `<div class="kicker">Day ${day.day} of 100</div><h1>${escapeHtml(day.title)}</h1>`;
  main.appendChild(header);

  // Lessons card (video player + tabs)
  main.appendChild(lessonsCard(day));

  // Exercises card
  if (day.exercises.length) main.appendChild(exercisesCard(day));

  // Project card
  if (day.project) main.appendChild(projectCard(day));

  // Complete-day toggle
  main.appendChild(completeCard(day));
}

function lessonsCard(day) {
  const card = el("div", "card");
  card.appendChild(el("h2", null, "Lessons"));

  const tabs = el("div", "lesson-tabs");
  const stage = el("div");
  card.appendChild(tabs);
  card.appendChild(stage);

  const showLesson = (idx) => {
    tabs.querySelectorAll(".lesson-tab").forEach((t, i) =>
      t.classList.toggle("active", i === idx));
    stage.innerHTML = "";
    const lesson = day.lessons[idx];

    const frame = el("div", "video-frame");
    if (lesson.youtube) {
      const iframe = document.createElement("iframe");
      iframe.src = `https://www.youtube.com/embed/${lesson.youtube}`;
      iframe.allow = "accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture";
      iframe.allowFullscreen = true;
      frame.appendChild(iframe);
    } else {
      frame.appendChild(el("div", "video-missing",
        `<div>Not rendered yet.</div>` +
        `<div class="hint">Render <code>${lesson.id}</code> (see 00_pipeline/RENDERING.md),` +
        ` upload to YouTube unlisted, then add its ID to <code>docs/videos.json</code>.</div>`));
    }
    stage.appendChild(frame);

    stage.appendChild(el("div", "lesson-title-row",
      `Lesson ${lesson.num}: ${escapeHtml(lesson.title)}`));

    const row = el("div", "item-row");
    const cb = checkbox(`${lesson.id}_watched`);
    const lbl = el("label", "label", "Mark lesson watched");
    lbl.prepend(cb);
    row.appendChild(lbl);
    stage.appendChild(row);
  };

  day.lessons.forEach((lesson, i) => {
    const tab = el("button", "lesson-tab", `L${lesson.num}`);
    if (itemDone(`${lesson.id}_watched`)) tab.textContent += " ✓";
    tab.onclick = () => showLesson(i);
    tabs.appendChild(tab);
  });

  showLesson(0);
  return card;
}

function exercisesCard(day) {
  const card = el("div", "card");
  card.appendChild(el("h2", null, `Exercises (${day.exercises.length})`));
  card.appendChild(el("p", "hint",
    "Runs on Google Colab — Google's compute, not your machine."));
  day.exercises.forEach(ex => {
    const row = el("div", "item-row");
    const key = `day_${day.day}_ex_${ex.num}`;
    const lbl = el("label", "label");
    lbl.prepend(checkbox(key));
    lbl.append(` Exercise ${ex.num}`);
    row.appendChild(lbl);
    row.appendChild(colabBtn(ex.colab));
    card.appendChild(row);
  });
  return card;
}

function projectCard(day) {
  const card = el("div", "card");
  card.appendChild(el("h2", null, "Project"));
  const row = el("div", "item-row");
  const lbl = el("label", "label");
  lbl.prepend(checkbox(`day_${day.day}_project`));
  lbl.append(" Build the day's project");
  row.appendChild(lbl);
  row.appendChild(colabBtn(day.project.colab));
  card.appendChild(row);
  return card;
}

function completeCard(day) {
  const card = el("div", "card");
  const row = el("div", "item-row");
  const lbl = el("label", "label");
  const cb = checkbox(`day_${day.day}_complete`, () => {
    renderSidebar(); markActive(day.day); updateSummary();
  });
  lbl.prepend(cb);
  lbl.append(` Mark Day ${day.day} complete`);
  row.appendChild(lbl);
  card.appendChild(row);
  return card;
}

// ── Small helpers ─────────────────────────────────────────────────────────────
function colabBtn(url) {
  const a = document.createElement("a");
  a.className = "btn btn-colab";
  a.href = url;
  a.target = "_blank";
  a.rel = "noopener";
  a.textContent = "Open in Colab ↗";
  return a;
}

function checkbox(key, onChange) {
  const cb = document.createElement("input");
  cb.type = "checkbox";
  cb.checked = itemDone(key);
  cb.onchange = () => { setItem(key, cb.checked); if (onChange) onChange(); };
  return cb;
}

function el(tag, cls, html) {
  const e = document.createElement(tag);
  if (cls) e.className = cls;
  if (html != null) e.innerHTML = html;
  return e;
}

function escapeHtml(s) {
  return String(s).replace(/[&<>"']/g, c =>
    ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c]));
}
